import random
from sc2 import maps, run_game, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.constants import *
from sc2.position import Point2
from sc2.bot_ai import BotAI

class ProtossBot(BotAI):
    async def on_start(self):
        self.proxy_pylon_built = False
        self.proxy_pylon_position = None

    async def on_step(self, iteration):
        await self.distribute_workers()
        await self.build_workers()
        await self.build_pylons()
        await self.build_assimilators()
        await self.build_gateway()
        await self.build_cybercore()
        await self.research_warpgate()
        await self.morph_gateways()
        await self.build_proxy_pylon()
        await self.warp_units()
        await self.chrono_boost()
        await self.attack()

    async def build_workers(self):
        for nexus in self.townhalls.ready.idle:
            if self.can_afford(PROBE) and self.workers.amount < self.townhalls.amount * 22:
                nexus.train(PROBE)

    async def build_pylons(self):
        if self.supply_left < 5 and not self.already_pending(PYLON):
            nexuses = self.townhalls.ready
            if nexuses.exists and self.can_afford(PYLON):
                pos = nexuses.random.position.towards(self.game_info.map_center, 5)
                await self.build(PYLON, near=pos)

    async def build_assimilators(self):
        for nexus in self.townhalls.ready:
            vgs = self.vespene_geyser.closer_than(15.0, nexus)
            for vg in vgs:
                if not self.gas_buildings.closer_than(1.0, vg).exists and self.can_afford(ASSIMILATOR):
                    worker = self.select_build_worker(vg.position)
                    if worker and not self.worker_en_route_to_build(vg.position):
                        await self.do(worker.build(ASSIMILATOR, vg))

    async def build_gateway(self):
        if self.structures(PYLON).ready.exists:
            pylon = self.structures(PYLON).ready.random
            if self.structures(GATEWAY).amount < 2 and self.can_afford(GATEWAY) and not self.already_pending(GATEWAY):
                await self.build(GATEWAY, near=pylon)

    async def build_cybercore(self):
        if self.structures(GATEWAY).ready.exists and self.structures(CYBERNETICSCORE).amount < 1:
            pylon = self.structures(PYLON).ready.random
            if self.can_afford(CYBERNETICSCORE) and not self.already_pending(CYBERNETICSCORE):
                await self.build(CYBERNETICSCORE, near=pylon)

    async def research_warpgate(self):
        for core in self.structures(CYBERNETICSCORE).ready.idle:
            if self.can_afford(RESEARCH_WARPGATE) and not self.already_pending_upgrade(UpgradeId.WARPGATERESEARCH):
                core.research(RESEARCH_WARPGATE)

    async def morph_gateways(self):
        if self.already_pending_upgrade(UpgradeId.WARPGATERESEARCH) or self.structures(WARPGATE).exists:
            for gateway in self.structures(GATEWAY).ready:
                abilities = await self.get_available_abilities(gateway)
                if AbilityId.MORPH_WARPGATE in abilities:
                    gateway(AbilityId.MORPH_WARPGATE)

    async def build_proxy_pylon(self):
        if not self.proxy_pylon_built and self.structures(PYLON).ready.exists:
            enemy_location = self.enemy_start_locations[0]
            pos = enemy_location.towards(self.game_info.map_center, 20)
            placement = await self.find_placement(PYLON, pos, placement_step=2)
            if placement and self.can_afford(PYLON):
                await self.build(PYLON, near=placement)
                self.proxy_pylon_built = True
                self.proxy_pylon_position = placement

    async def warp_units(self):
        if self.structures(WARPGATE).ready.exists and (self.proxy_pylon_position or self.structures(PYLON).ready.exists):
            for warpgate in self.structures(WARPGATE).ready.idle:
                abilities = await self.get_available_abilities(warpgate)
                if AbilityId.WARPGATETRAIN_STALKER in abilities and self.can_afford(STALKER):
                    pylon = None
                    if self.proxy_pylon_position:
                        pylon = self.proxy_pylon_position
                    else:
                        pylon = self.structures(PYLON).ready.random.position
                    placement = await self.find_placement(STALKER, near=pylon, placement_step=1)
                    if placement:
                        warpgate.warp_in(STALKER, placement)

    async def chrono_boost(self):
        for nexus in self.townhalls.ready:
            if nexus.energy >= 50:
                # Prioritize Cybercore, then Nexus
                target = self.structures(CYBERNETICSCORE).ready.first if self.structures(CYBERNETICSCORE).ready.exists else nexus
                abilities = await self.get_available_abilities(nexus)
                if AbilityId.EFFECT_CHRONOBOOSTENERGYCOST in abilities:
                    nexus(AbilityId.EFFECT_CHRONOBOOSTENERGYCOST, target)

    async def attack(self):
        stalkers = self.units(STALKER).idle
        if stalkers.exists:
            targets = self.enemy_units
            if targets.exists:
                for stalker in stalkers:
                    stalker.attack(targets.closest_to(stalker))
            else:
                for stalker in stalkers:
                    stalker.attack(self.enemy_start_locations[0])

    async def on_end(self, result):
        pass

    async def on_unit_destroyed(self, unit_tag):
        # If all Nexuses are destroyed, do nothing (bot will lose)
        if not self.townhalls.exists:
            return

def main():
    run_game(
        maps.get("(2)CatalystLE"),
        [
            Bot(Race.Protoss, ProtossBot()),
            Computer(Race.Protoss, Difficulty.Easy)
        ],
        realtime=False,
    )

if __name__ == "__main__":
    main()
